export default function install(app){const panel=document.querySelector('section[aria-label="Thema\'s"]');const search=document.getElementById('app-widget-place-search');app.assert(panel&&search,'Thema panel and search are required');const style=document.createElement('style');document.head.append(style);app.onCleanup(()=>style.remove());const sync=()=>{const shadow=getComputedStyle(panel).boxShadow;style.textContent='#app-widget-place-search.app-sdk-widget {box-shadow:'+shadow+'!important;}';};sync();const observer=new MutationObserver(sync);observer.observe(panel,{attributes:true,attributeFilter:['style','class']});app.onCleanup(()=>observer.disconnect());const actual=getComputedStyle(search).boxShadow,expected=getComputedStyle(panel).boxShadow;app.assert(actual===expected,'Search shadow did not match');const inner=document.getElementById('app-widget-host-place-search').shadowRoot.querySelector('.content-container');return {themaShadow:expected,searchShadow:actual,matching:actual===expected,searchRadius:getComputedStyle(search).borderRadius,emptyWrapperBackground:getComputedStyle(inner).backgroundColor,emptyWrapperShadow:getComputedStyle(inner).boxShadow};}